fn is_name(t: Str) -> Bool {
  if t.len() == 0 {
    return false
  }
  return t.chars().all(fn(c) => "abcdefghijklmnopqrstuvwxyz".contains(c))
}

fn is_digits(s: Str) -> Bool {
  if s.len() == 0 {
    return false
  }
  return s.chars().all(fn(c) => "0123456789".contains(c))
}

fn is_number(t: Str) -> Bool {
  if t.starts_with("-") {
    return is_digits(t.slice(1, t.len()))
  }
  return is_digits(t)
}

fn is_term(t: Str) -> Bool {
  return is_name(t) or is_number(t)
}

fn number_value(t: Str) -> Int {
  if t.starts_with("-") {
    return 0 - t.slice(1, t.len()).to_int().unwrap_or(0)
  }
  return t.to_int().unwrap_or(0)
}

fn check_line(parts: List[Str]) -> Bool {
  let n = parts.len()
  if n < 3 or n % 2 == 0 {
    return false
  }
  if not is_name(parts.get_or(0, "")) {
    return false
  }
  if parts.get_or(1, "") != "=" {
    return false
  }
  if not is_term(parts.get_or(2, "")) {
    return false
  }
  var k = 3
  while k < n {
    let op = parts.get_or(k, "")
    if op != "+" and op != "-" {
      return false
    }
    if not is_term(parts.get_or(k + 1, "")) {
      return false
    }
    k = k + 2
  }
  return true
}

fn term_value(vars: Map[Str, Int], t: Str) -> Result[Int, Str] {
  if is_name(t) {
    return vars.get(t).ok_or("undefined {t}")
  }
  return Ok(number_value(t))
}

pub fn run_vars(lines: List[Str]) -> Result[Map[Str, Int], Str] {
  let empty: Map[Str, Int] = Map {}
  var vars: Map[Str, Int] = empty
  for line in lines {
    let parts = line.split(" ")
    if not check_line(parts) {
      return Err("syntax error")
    }
    let target = parts.get_or(0, "")
    let start = term_value(vars, parts.get_or(2, ""))?
    var acc: Int = start
    var k = 3
    while k < parts.len() {
      let v = term_value(vars, parts.get_or(k + 1, ""))?
      if parts.get_or(k, "") == "+" {
        acc = acc + v
      } else {
        acc = acc - v
      }
      k = k + 2
    }
    vars = vars.set(target, acc)
  }
  return Ok(vars)
}
